import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceFamily } = loadSpaceGrotesk();



export type RealEstateRentTipProps = Record<string, any>;

const RealEstateRentTip: React.FC<RealEstateRentTipProps> = ({
  backgroundColor = "#0A0A0A",
  transparentBackground = false,
  durationInSeconds = 12,
  cardBackgroundColor = "#171717",
  primaryAccentColor = "#10B981", // Emerald Green
  secondaryAccentColor = "#EAB308", // Amber/Yellow
  titleTextColor = "#FFFFFF",
  bodyTextColor = "#A3A3A3",
  titleText = "The Rent Rule",
  topPercentage = 33,
  topLabel = "Higher Collected Rent",
  bottomPercentage = 75,
  bottomDescription = "Lenders only let you claim 75% of the lease agreement rent to qualify for buying the property.",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Background Transparency Logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings - Stretched out to span ~9 seconds (keeping viewers hooked)
  const titleY = spring({ frame, fps, config: { damping: 14 } });

  const card1Pop = spring({ frame: frame - 40, fps, config: { damping: 12, mass: 1.1 } });
  
  // Slow count over 2 seconds (60 frames) instead of a quick spring
  const card1CountProgress = interpolate(frame, [60, 120], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Staggered connector animation
  const arrowTextPop = spring({ frame: frame - 130, fps, config: { damping: 12 } });
  const arrowLineDrop = spring({ frame: frame - 145, fps, config: { damping: 14 } });
  const arrowTipDrop = spring({ frame: frame - 160, fps, config: { damping: 14 } });

  const card2Pop = spring({ frame: frame - 180, fps, config: { damping: 12, mass: 1.1 } });
  
  // Slow count over 2 seconds
  const card2CountProgress = interpolate(frame, [200, 260], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const bottomTextOp = spring({
    frame: frame - 250,
    fps,
    config: { damping: 16 },
  });

  // Continuous subtle floating to keep it visually interesting
  const card1Float = Math.sin(frame / 30) * 8;
  const card2Float = Math.cos(frame / 35) * 8;

  // Safe Interpolation Values
  const animatedTopValue = Math.round(
    interpolate(card1CountProgress, [0, 1], [0, topPercentage])
  );

  const animatedBottomValue = Math.round(
    interpolate(card2CountProgress, [0, 1], [0, bottomPercentage])
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          width: "100%",
          height: "100%",
          padding: "15% 8% 10% 8%",
          boxSizing: "border-box",
        }}
      >
        {/* Title */}
        <h1
          style={{
            fontFamily: spaceFamily,
            fontSize: 64,
            color: titleTextColor,
            transform: `translateY(${interpolate(titleY, [0, 1], [-50, 0])}px)`,
            opacity: titleY,
            marginBottom: 60,
            textAlign: "center",
            textTransform: "uppercase",
            letterSpacing: 2,
          }}
        >
          {titleText}
        </h1>

        {/* Card 1: Goal */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            backgroundColor: cardBackgroundColor,
            width: "100%",
            padding: "50px 40px",
            borderRadius: 32,
            border: `3px solid ${primaryAccentColor}`,
            transform: `translateY(${card1Float}px) scale(${card1Pop})`,
            opacity: card1Pop,
            boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.5)",
          }}
        >
          <h2
            style={{
              fontFamily: spaceFamily,
              fontSize: 160,
              color: primaryAccentColor,
              margin: 0,
              lineHeight: 1,
            }}
          >
            +{animatedTopValue}%
          </h2>
          <p
            style={{
              fontSize: 42,
              color: titleTextColor,
              margin: "20px 0 0 0",
              textAlign: "center",
              fontWeight: 600,
              opacity: interpolate(card1CountProgress, [0.5, 1], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
            }}
          >
            {topLabel}
          </p>
        </div>

        {/* Connector Arrow (Staggered) */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            height: 180,
            margin: "20px 0",
          }}
        >
          <div
            style={{
              backgroundColor: cardBackgroundColor,
              color: titleTextColor,
              padding: "12px 24px",
              borderRadius: 20,
              border: `2px solid #333`,
              fontFamily: spaceFamily,
              fontSize: 24,
              fontWeight: "bold",
              zIndex: 10,
              letterSpacing: 3,
              transform: `scale(${arrowTextPop})`,
            }}
          >
            BECAUSE
          </div>
          <div
            style={{
              width: 6,
              height: 120,
              backgroundColor: secondaryAccentColor,
              transformOrigin: "top",
              transform: `scaleY(${arrowLineDrop})`,
              marginTop: -15,
            }}
          />
          <div
            style={{
              width: 24,
              height: 24,
              borderRight: `6px solid ${secondaryAccentColor}`,
              borderBottom: `6px solid ${secondaryAccentColor}`,
              transform: `rotate(45deg) scale(${arrowTipDrop})`,
              marginTop: -12,
            }}
          />
        </div>

        {/* Card 2: Limitation/Reason */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            backgroundColor: cardBackgroundColor,
            width: "100%",
            padding: "50px 40px",
            borderRadius: 32,
            border: `3px solid ${secondaryAccentColor}`,
            transform: `translateY(${card2Float}px) scale(${card2Pop})`,
            opacity: card2Pop,
            boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.5)",
          }}
        >
          <h2
            style={{
              fontFamily: spaceFamily,
              fontSize: 160,
              color: secondaryAccentColor,
              margin: 0,
              lineHeight: 1,
            }}
          >
            {animatedBottomValue}%
          </h2>
          <p
            style={{
              fontSize: 38,
              color: bodyTextColor,
              margin: "30px 0 0 0",
              textAlign: "center",
              lineHeight: 1.4,
              opacity: bottomTextOp,
              transform: `translateY(${interpolate(bottomTextOp, [0, 1], [20, 0])}px)`,
            }}
          >
            {bottomDescription}
          </p>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default RealEstateRentTip;